--
-- Estructura de tabla para la tabla `activity_logs`
--

CREATE TABLE `activity_logs` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED DEFAULT NULL,
  `actor_id` bigint(20) UNSIGNED DEFAULT NULL,
  `event` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `subject_type` varchar(255) DEFAULT NULL,
  `subject_id` bigint(20) UNSIGNED DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `metadata` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`metadata`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Estructura de tabla para la tabla `ai_contexts`
--

CREATE TABLE `ai_contexts` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `listing_id` bigint(20) UNSIGNED NOT NULL,
  `title` varchar(255) NOT NULL,
  `content` text NOT NULL,
  `content_for_editing` text DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Volcado de datos para la tabla `ai_contexts`
--

INSERT INTO `ai_contexts` (`id`, `listing_id`, `title`, `content`, `content_for_editing`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 6, 'asdasd', 'La Copa Mundial de la FIFA 2026 concluyó el pasado 19 de julio con la selección de España coronándose como campeona tras vencer 1-0 a Argentina en el MetLife Stadium de Nueva York/Nueva Jersey. Esta edición fue histórica por ser la primera coorganizada por tres países (Estados Unidos, México y Canadá) y por expandirse a un formato de 48 selecciones y 104 partidos. [1, 2, 3, 4]', '<div>La <strong>Copa Mundial de la FIFA 2026</strong> concluyó el pasado 19 de julio con la selección de <strong>España coronándose como campeona</strong> tras vencer 1-0 a Argentina en el MetLife Stadium de Nueva York/Nueva Jersey. Esta edición fue histórica por ser la primera coorganizada por tres países (<strong>Estados Unidos, México y Canadá</strong>) y por expandirse a un formato de <strong>48 selecciones y 104 partidos</strong>. [<a href=\"https://es.wikipedia.org/wiki/Copa_Mundial_de_F%C3%BAtbol_de_2026\">1</a>, <a href=\"https://support.google.com/knowledgepanel/answer/9787176\">2</a>, <a href=\"https://en.wikipedia.org/wiki/2026_FIFA_World_Cup\">3</a>, <a href=\"https://www.fifa.com/es/tournaments/mens/worldcup/canadamexicousa2026\">4</a>]</div>', 1, '2026-08-21 10:09:08', '2026-08-21 10:09:08'),
(2, 2, 'Acerca de Orpot.com | orpot.com', 'Inicio Sitios Web Diseño de Sitios Web Paginas de aterrizaje Sitios web Administrables Tiendas en linea Funnels de Venta Desarrollo Web Wordpress Drupal Processwire SERVICIOS WEB Posicionamiento SEO Hosting Web Acerca Portafolio Blog Articulos Contáctenos Experiencia en Desarrollo Web Equipo de Profesionales con Experiencia en el Desarrollo de Sitios Web Somos un equipo de apasionados por la web con años de experiencia. Nos hemos unido para formar un grupo de desarrollo web capaz de ofrecer una amplia gama de servicios a clientes en cualquier parte del mundo. Nuestro objetivo es proporcionar servicios excepcionales que impulsen el éxito en línea de nuestros clientes y les ayuden a destacarse en un entorno digital cada vez más Nos especializamos en el diseño y desarrollo de sitios en plataformas como Wordpress/Woocommerce , Processwire y Drupal , ademas de otros servicios como son posicionamiento y Hosting dedicado . ¿Por qué elegir nuestros servicios de diseño y desarrollo web ? Además de nuestro expertise técnico, nos guiamos por una sólida línea de trabajo y valores que aplicamos en todos nuestros proyectos y con cada cliente. Somos Experimentados Durante más de una década, hemos perfeccionado nuestra capacidad para abordar rápidamente sus necesidades y encontrar soluciones eficientes, garantizando que se cumplan los plazos de entrega sin contratiempos ni retrasos inesperados. Manejamos Tarifas Detalladas Trabajamos con presupuestos detallados, lo que garantiza que tanto usted como nosotros conozcamos el precio final desde el principio, sin sorpresas ni costos adicionales al finalizar el proyecto. Equipo de Trabajo Nuestro enfoque es 100% profesional y está centrado en alcanzar metas. Puede estar seguro de que no tendrá que preocuparse por los plazos de entrega, ya que siempre llegaremos a la meta. Somos Honestos Forjamos relaciones comerciales duraderas con múltiples clientes, basadas en la honestidad y la transparencia. Estos valores son fundamentales en nuestro enfoque profesional. Somos Confiables Nos comprometemos a brindarle una atención completa y dedicada desde el primer momento en que nos contacte. Su proyecto será nuestra prioridad absoluta, y trabajaremos diligentemente para comprender sus necesidades, objetivos y expectativas. Somos Comunicativos No evadimos llamadas telefónicas ni ignoramos correos electrónicos; en su lugar, puede confiar en que recibirá una respuesta rápida y oportuna de nuestra parte. ¿Qué dicen nuestros clientes ? Algunos testimonios de clientes con los que tenemos más de 10 años trabajando. Estoy enormemente agradecido por el excelente trabajo de Orpot.com. Su atención personalizada y el diseño web de alta calidad han sido fundamentales para el crecimiento de mi negocio. ¡Gracias a ellos, mi empresa ha experimentado un aumento significativo en su visibilidad en línea y en sus ventas! Ana Luisa R. Orpot.com ha sido un verdadero socio en el éxito de mi negocio. Desde el primer contacto, su equipo ha demostrado un compromiso excepcional con la satisfacción del cliente. Alejandro Marti Estoy muy agradecida con Daniel y su equipo, fueron muy profesionales desde el principio y puntuales con la entrega de mi nuevo sitio web. Lulu Carbajal ¡Contáctenos ahora mismo para conocer su proyecto ! Complete el formulario a continuación y comenzaremos a explorar las opciones para su nuevo sitio web. Enviar Enviando formulario... ¿Seria mejor una charla por teléfono o Whatsapp ? Programe una llamada de 20 minutos para revisar las necesidades de su proyecto de sitio web. Enviar Enviando formulario... Cotizar Servicio × Para nuevos proyectos, por favor llene este formulario. Si no está seguro o prefiere chatear, póngase en contacto . Los campos marcados con * son obligatorios ¿Que tipo de negocio tiene? Individual Compañia Agencia ¿Que tipo de Proyecto Requiere? Sitio Web Presupuesto aproximado Es : Empresa Independiente Agencia Comentarios. Nombre : Email : Telefono / Whats app : Ciudad / Estado Enviar Resumen Cerrar', '<div>Inicio Sitios Web Diseño de Sitios Web Paginas de aterrizaje Sitios web Administrables Tiendas en linea Funnels de Venta Desarrollo Web Wordpress Drupal Processwire SERVICIOS WEB Posicionamiento SEO Hosting Web Acerca Portafolio Blog Articulos Contáctenos Experiencia en Desarrollo Web Equipo de Profesionales con Experiencia en el Desarrollo de Sitios Web Somos un equipo de apasionados por la web con años de experiencia. Nos hemos unido para formar un grupo de desarrollo web capaz de ofrecer una amplia gama de servicios a clientes en cualquier parte del mundo. Nuestro objetivo es proporcionar servicios excepcionales que impulsen el éxito en línea de nuestros clientes y les ayuden a destacarse en un entorno digital cada vez más Nos especializamos en el diseño y desarrollo de sitios en plataformas como Wordpress/Woocommerce , Processwire y Drupal , ademas de otros servicios como son posicionamiento y Hosting dedicado . ¿Por qué elegir nuestros servicios de diseño y desarrollo web ? Además de nuestro expertise técnico, nos guiamos por una sólida línea de trabajo y valores que aplicamos en todos nuestros proyectos y con cada cliente. Somos Experimentados Durante más de una década, hemos perfeccionado nuestra capacidad para abordar rápidamente sus necesidades y encontrar soluciones eficientes, garantizando que se cumplan los plazos de entrega sin contratiempos ni retrasos inesperados. Manejamos Tarifas Detalladas Trabajamos con presupuestos detallados, lo que garantiza que tanto usted como nosotros conozcamos el precio final desde el principio, sin sorpresas ni costos adicionales al finalizar el proyecto. Equipo de Trabajo Nuestro enfoque es 100% profesional y está centrado en alcanzar metas. Puede estar seguro de que no tendrá que preocuparse por los plazos de entrega, ya que siempre llegaremos a la meta. Somos Honestos Forjamos relaciones comerciales duraderas con múltiples clientes, basadas en la honestidad y l