(1, 'Trial ending reminder', 'billing.trial_ending', 'send_email', 1, '{\"days_before\":3,\"template_key\":\"trial_ending\",\"subject\":\"Tu trial esta por terminar\",\"message\":\"Tu periodo de prueba terminara pronto. Revisa tu plan en el panel.\"}', '2026-08-20 08:47:25', '2026-08-20 08:47:25'),
(2, 'Payment failed notification', 'billing.payment_failed', 'create_notification', 1, '{\"category\":\"billing\",\"template_key\":\"payment_failed\",\"title\":\"Pago fallido\",\"message\":\"Detectamos un pago fallido. Actualiza tu metodo de pago.\",\"url\":\"\\/member\\/payments\"}', '2026-08-20 08:47:25', '2026-08-20 08:47:25'),
(3, 'Ticket idle reminder', 'support.ticket_idle', 'notify_admin', 1, '{\"idle_hours\":48,\"title\":\"Ticket sin respuesta\",\"message\":\"Hay un ticket sin actividad reciente.\",\"url\":\"\\/admin\\/support\"}', '2026-08-20 08:47:25', '2026-08-20 08:47:25'),
(4, 'Webhook failure alert', 'webhook.failed_many_times', 'notify_admin', 1, '{\"threshold\":3,\"window_hours\":24,\"title\":\"Fallos de webhook\",\"message\":\"Se detectaron multiples fallos de webhook.\",\"url\":\"\\/admin\\/webhooks\"}', '2026-08-20 08:47:25', '2026-08-20 08:47:25'),
(5, 'Profile incomplete reminder', 'user.profile_incomplete', 'create_notification', 1, '{\"category\":\"product\",\"title\":\"Completa tu perfil\",\"message\":\"Actualiza tu perfil para aprovechar el sistema.\",\"url\":\"\\/member\\/profile\",\"days_since_signup\":7}', '2026-08-20 08:47:25', '2026-08-20 08:47:25'),
(6, 'Subscription expired', 'subscription.expired', 'create_notification', 1, '{\"category\":\"billing\",\"title\":\"Suscripcion expirada\",\"message\":\"Tu suscripcion expiro. Revisa los planes disponibles.\",\"url\":\"\\/pricing\"}', '2026-08-20 08:47:25', '2026-08-20 08:47:25'),
(7, 'Subscription canceled', 'subscription.canceled', 'create_notification', 1, '{\"category\":\"billing\",\"title\":\"Suscripcion cancelada\",\"message\":\"Tu suscripcion fue cancelada.\",\"url\":\"\\/member\\/account\"}', '2026-08-20 08:47:25', '2026-08-20 08:47:25');

