--
-- Estructura de tabla para la tabla `listing_module_definitions`
--

CREATE TABLE `listing_module_definitions` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `key` varchar(255) NOT NULL COMMENT 'Unique identifier: locations, gallery, appointments, etc.',
  `name` varchar(255) NOT NULL COMMENT 'Display name in Spanish',
  `description` text DEFAULT NULL,
  `icon` varchar(255) DEFAULT NULL COMMENT 'Bootstrap icon class',
  `image` varchar(255) DEFAULT NULL COMMENT 'Image URL for module illustration',
  `sort_order` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_premium` tinyint(1) NOT NULL DEFAULT 0,
  `has_settings` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Whether module has custom settings',
  `show_in_menu` tinyint(1) NOT NULL DEFAULT 0,
  `menu_title` varchar(50) DEFAULT NULL,
  `settings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`settings`)),
  `settings_schema` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`settings_schema`)),
  `settings_url` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

